def t(key: str, lang: str = None) -> str:
    if lang is None:
        from ..i18n import get_language
        lang = get_language()
    table = TRANSLATIONS.get(lang, TRANSLATIONS["en"])
    if key in table:
        return table[key]
    # fallback to English
    return TRANSLATIONS["en"].get(key, key)


def available_languages():
    return list(TRANSLATIONS.keys())
